  OwnerUIBounds: Rectangle;
  OwnerType: number;
  /**
   * @default 0
   */
  CurrentMaxGuests: number;
  readonly WaitGuests: boolean;
  InputType: any;
  /**
   * @default "*"
   */
  IdealProcessor: string;
  /**
   * @default ""
   */
  Affinity: string;
  /**
   * @default "Normal"
   */
  PriorityClass: string;
  GamepadName: string;
  HIDDeviceID: string[];
  Nickname: string;
  InstanceId: string;
  RawHID: string;
  SID: string;
  Adapter: string;
  UserProfile: string;
  /**
   * @default new List<PlayerInfo>()
   */
  InstanceGuests: PlayerInfo[];
  /**
   * @default new List<Guid>()
   */
  GuestsGuid: any[];
  /**
   * If the player is instance guest
   */
  GuestBounds: Rectangle;
  SteamEmu: boolean;
  GotLauncher: boolean;
  GotGame: boolean;
  Polling: boolean;
  IsRawMouse: boolean;
  IsRawKeyboard: boolean;
  IsKeyboardPlayer: boolean;
  IsXInput: boolean;
  IsSDL2: boolean;
  IsDInput: boolean;
  IsFake: boolean;
  IsInputUsed: boolean;
  /**
   * Good to do not have to loop both Xinput & DInput
   */
  IsController: boolean;
  Vibrate: boolean;
  GamepadProductGuid: any;
  GamepadGuid: any;
  Display: any;
  Owner: any;
  DInputJoystick: any;
  XInputJoystick: any;
  SDL2Joystick: any;
  RawInputWindow: any;
  /**
   * "IsMinimzed" used to sync all players window state if the window is not minimized by Nucleus and some other cases.
   */
  IsMinimized: boolean;
  SteamID: number;
  /**
   * @default 0
   */
  ProtoInputInstanceHandle: number;
  /**
   * @default 0
   */
  CurrentLayout: number;
  ScreenPriority: number;
  /**
   * @default -1
   */
  GamepadId: number;
  GamepadMask: number;
  /**
   * @default -1
   */
  DisplayIndex: number;
  /**
   * @default -1
   */
  PlayerID: number;
  ProcessID: number;
  ProtoController1: number;
  ProtoController2: number;
  ProtoController3: number;
  ProtoController4: number;
  /**
   * @default (IntPtr)(-1)
   */
